export function getInventoryByHub(hub: InventoryHub): ArticleInventoryItem[] {
  return articleInventory.filter((item) => item.hub === hub);
}

export function getInventoryByDuplicateRisk(
  risk: DuplicateRisk
): ArticleInventoryItem[] {
  return articleInventory.filter((item) => item.duplicateRisk === risk);
}
